template <class T> class Ring {
  std::vector<T> buf_; std::atomic<std::size_t> head_{0}, tail_{0};
  std::counting_semaphore<> empty_, full_{0};
 public:
  explicit Ring(std::size_t cap) : buf_(cap), empty_(cap) {}
  void push(T v) {
    empty_.acquire();
    buf_[tail_.fetch_add(1) % buf_.size()] = std::move(v);
    full_.release();
  }
  /* pop(): full_.acquire(); take and advance head_; empty_.release(); */
};
